 public static boolean ready(int id,IntPredicate done){for(int p:PREREQUISITES[id])if(!done.test(p))return false;return true;}
 public static int recommend(IntPredicate done){for(int id:ORDER)if(!done.test(id)&&ready(id,done))return id;return -1;}
 public static int target(int id){return switch(id){case 80 -> 100;case 81 -> 64;case 82 -> 32;case 83 -> 10;case 84 -> 10;case 85 -> 10;case 86 -> 1;case 87 -> 1;case 91 -> 3;case 93 -> 1000;case 89,90 -> 6;case 92,94 -> 8;default -> 1;};}
 public static int progress(ServerPlayer p,int id){return switch(id){case 80 -> Progression.counter(p,"AshenJobs");case 81 -> Progression.counter(p,"AshenAutoOutputs");case 82 -> Progression.counter(p,"AshenHarvests");case 83 -> Progression.counter(p,"AshenContracts");case 84 -> Progression.counter(p,"AshenMedicalUses");case 85 -> Progression.counter(p,"AshenPhaseJobs");case 86 -> Progression.counter(p,"AshenBiosphereJobs");case 87 -> Progression.counter(p,"AshenAnchorJobs");case 91 -> Progression.counter(p,"AshenArenaWins");case 93 -> Progression.counter(p,"AshenJobs");case 89 -> Integer.bitCount(Progression.counter(p,"AshenLostVisits"));case 90 -> Integer.bitCount(Progression.counter(p,"AshenDeepVisits"));case 92 -> Integer.bitCount(Progression.counter(p,"AshenBossKills"));case 94 -> Integer.bitCount(Progression.counter(p,"AshenHarvestKinds"));default -> Progression.completed(p,id)?1:0;};}
 public static String condition(int id){return switch(id){case 3 -> "实际成功开火一次";case 4 -> "背包持有因果回声残渣";case 6 -> "实际使用一次净化器";case 7 -> "主动净化已完成，完整度≥3000、熵债<1000";case 17 -> "同时持有霜镜与日轮";case 23 -> "坐标核心记录完成，完整度≥8000、熵债<500";case 51 -> "成功提交一次委托";case 61,66,71,75 -> "亲自击败对应首领";case 78 -> "完成一次六波远征";case 79 -> "曙光战与远征完成，完整度≥9500、熵债<200";case 89,90 -> "实际走访全部六类原创群系";case 92 -> "亲自击败八种首领各一次";case 94 -> "亲自收获八种成熟原创作物";case 95 -> "完整复苏已完成，完整度10000、熵债0";default -> id>=80 ? "累计真实行动达到目标值" : "背包持有目标物品；不额外扣除";};}
 public static String hint(int id){return switch(id){case 0->"紫水晶 + 四份红石 → 协议碎片";case 1->"指南针、红石与碎片 → 熵表";case 8->"铁镐开采 Y=0～72 的灰烬矿";case 9->"压制原灰矿，获取灰烬锭";case 12->"哨站祭坛使用余烬钥匙";case 51->"契约终端手持足量材料提交";case 78->"信标使用封印，清除六波敌人";default->"按 J 查看配方、材料与操作步骤";};}
 public static int reward(int id){return 15+Math.min(id,30)*5;}
 public static int[] progressValues(ServerPlayer p){int[] v=new int[96];for(int i=0;i<v.length;i++)v[i]=Math.min(target(i),progress(p,i));return v;}
